from collections import defaultdict, deque
import math

def distance(x1, y1, x2, y2):
    return math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)

def chapare_protegido(n, stations):
    if n == 0:
        return False

    graph = defaultdict(list)

    for i in range(n):
        x1, y1 = stations[i]
        distances = []
        for j in range(n):
            if i != j:
                x2, y2 = stations[j]
                dist = (math.sqrt(((x1) - (x2)) ** 2 + ((y1) - (y2)) ** 2))
                distances.append((dist, x2, y2, j))

        distances.sort(key=lambda x: (x[0], x[1], x[2]))

        if len(distances) >= 2:
            graph[i].append(distances[0][3])
            graph[i].append(distances[1][3])
        elif len(distances) == 1:
            graph[i].append(distances[0][3])

    visited = set()
    queue = deque([0])
    visited.add(0)

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return len(visited) == n

def main():
    while True:
        n = int(input())
        if n == 0:
            break

        stations = []
        for _ in range(n):
            x, y = map(int, input().split())
            stations.append((x, y))

        if chapare_protegido(n, stations):
            print("Chapare protegido")
        else:
            print("Chapare no Protegido")

