def sieve_of_eratosthenes(max_num):
    primo = [True] * (max_num + 1)
    p = 2
    while (p * p <= max_num):
        if (primo[p]):
            for i in range(p * p, max_num + 1, p):
                primo[i] = False
        p += 1
    primes = [p for p in range(2, max_num + 1) if primo[p]]
    return primes

