def rotar_90(matriz):
    N = len(matriz)
    matriz_rotada = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            matriz_rotada[j][N - 1 - i] = matriz[i][j]
    return matriz_rotada

def rotar_180(matriz):
    # Rotar 180 grados es rotar 90 grados dos veces
