def criba_de_eratostenes(n):
    es_primo = [True] * (n + 1)
    es_primo[0] = es_primo[1] = False

    for i in range(2, math.isqrt(n) + 1):
        if es_primo[i]:
            for j in range(i * i, n + 1, i):
                es_primo[j] = False

    return [num for num in range(2, n + 1) if es_primo[num]]

def precalcular_factores_primos(max_n, primos):
    factores_primos = {i: set() for i in range(2, max_n + 1)}
    for primo in primos:
        for multiple in range(primo, max_n + 1, primo):
            factores_primos[multiple].add(primo)
    return factores_primos

def contar_factores_primos(n, factores_primos):
    return len(factores_primos[n])

def masGrande(a, b, factores_primos):
    if a == b:
        print(f"{b} tiene {(len((factores_primos)[(a)]))} divisores")
    else:
        max_divisores = 0
        num_con_max_divisores = a
        for i in range(a, b + 1):
            num_divisores = contar_factores_primos(i, factores_primos)
            if num_divisores >= max_divisores:
                max_divisores = num_divisores
                num_con_max_divisores = i
        print(f"{num_con_max_divisores} tiene {max_divisores} divisores")

