    matrix = []
    for _ in range(n):
        row = list(map(int, input().strip().split()))
        matrix.append(row)
    return matrix

def flip_vertical(matrix):
    return matrix[::-1]

def flip_horizontal(matrix):
    return [row[::-1] for row in matrix]

def matrices_equal(matrix1, matrix2):
    return all(row1 == row2 for row1, row2 in zip(matrix1, matrix2))

def find_transformation(original, target):
    if (all(row1 == row2 for row1, row2 in zip((original), (target)))):
        return "sin transformaciones"

    flipped_h = flip_horizontal(original)
    if matrices_equal(flipped_h, target):
        return "flip horizontal"

    flipped_v = flip_vertical(original)
    if matrices_equal(flipped_v, target):
        return "flip vertical"

    flipped_both = flip_horizontal(flip_vertical(original))
    if matrices_equal(flipped_both, target):
        return "flip vertical y flip horizontal"

    return "respuesta desconocida"

