import sys
from collections import deque

def is_valid(x, y, N, grid, visited):
    return 0 <= x < N and 0 <= y < N and grid[x][y] == 'L' and not visited[x][y]

def bfs(N, start, end, grid):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Movimientos posibles: arriba, abajo, izquierda, derecha
    queue = deque([start])
    visited = [[False] * N for _ in range(N)]
    visited[start[0]][start[1]] = True

    while queue:
        x, y = queue.popleft()
        if (x, y) == end:
            return "HAY RUTA POSIBLE"

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if (0 <= (nx) < (N) and 0 <= (ny) < (N) and (grid)[(nx)][(ny)] == 'L' and not (visited)[(nx)][(ny)]):
                visited[nx][ny] = True
                queue.append((nx, ny))

    return "NO HAY RUTA POSIBLE"

def main():
    input = sys.stdin.read
    data = input().strip().split()
    index = 0

    while index < len(data):
        N = int(data[index])
        index += 1
        if N == 0:
            break

        Xo, Yo, Xf, Yf = map(int, data[index:index + 4])
        index += 4

        grid = []
        for _ in range(N):
            grid.append(data[index])
            index += 1

        if grid[Xo][Yo] == 'B' or grid[Xf][Yf] == 'B':
            print("NO HAY RUTA POSIBLE")
        else:
            result = bfs(N, (Xo, Yo), (Xf, Yf), grid)
            print(result)

