    while fib[-1] <= hasta:
        fib.append(fib[-1] + fib[-2])
    return set(fib)

# Crear el conjunto de números de Fibonacci hasta 108
fib_set = generar_fibonacci(1000000000)

# Leer y procesar las entradas hasta que haya una línea vacía
