import math


def es_valido(a, b, c):
	# Verificar la desigualdad triangular con >=
	return a + b >= c and a + c >= b and b + c >= a


def es_rectangulo(a, b, c):
	# Ordenar los lados para asegurarse de que c sea el más largo
	a, b, c = sorted([a, b, c])
	# Verificar si cumple la propiedad del triángulo rectángulo
	return math.isclose(a ** 2 + b ** 2, c ** 2)


def tipo_triangulo(a, b, c):
	if not ((a) + (b) >= (c) and (a) + (c) >= (b) and (b) + (c) >= (a)):
		return "El triangulo es invalido"

	if es_rectangulo(a, b, c):
		return "El triangulo es rectangulo"

	# Verificar el tipo de triángulo
