def generar_secuencia_fibonacci(limite_maximo):
    secuencia_fib = [0, 1]
    while len(secuencia_fib) <= limite_maximo:
        secuencia_fib.append(secuencia_fib[-1] + secuencia_fib[-2])
    return secuencia_fib


def es_numero_primo(numero):
    if numero <= 1:
        return False 
    if numero <= 3:
        return True
    if numero % 2 == 0 or numero % 3 == 0:
        return False
    divisor = 5
    while divisor * divisor <= numero:
        if numero % divisor == 0 or numero % (divisor + 2) == 0:
            return False
        divisor += 6
    return True


def es_probablemente_primo(numero_grande, iteraciones=5):  
    if numero_grande <= 1:
        return False  
    if numero_grande <= 3:
        return True
    if numero_grande % 2 == 0:
        return False


    r = 0
    d = numero_grande - 1
    while d % 2 == 0:
        d //= 2
        r += 1


    for _ in range(iteraciones):
        a = random.randint(2, numero_grande - 2)
        x = pow(a, d, numero_grande)
        if x == 1 or x == numero_grande - 1:
            continue
        for _ in range(r - 1):
            x = pow(x, 2, numero_grande)
            if x == numero_grande - 1:
                break
        else:
            return False
    return True


def termina_en_1(numero):
    return numero % 10 == 1


