import math


# Exponenciación de matrices para obtener el n-ésimo número de Fibonacci en tiempo O(log n)
def fibonacci(n):
    """Calcula el n-ésimo número de Fibonacci usando exponenciación de matrices."""

    def matrix_mult(A, B):
        return [[A[0][0] * B[0][0] + A[0][1] * B[1][0], A[0][0] * B[0][1] + A[0][1] * B[1][1]],
                [A[1][0] * B[0][0] + A[1][1] * B[1][0], A[1][0] * B[0][1] + A[1][1] * B[1][1]]]

    def matrix_pow(M, p):
        result = [[1, 0], [0, 1]]  # Matriz identidad
        base = M
        while p:
            if p % 2 == 1:
                result = matrix_mult(result, base)
            base = ([[(base)[0][0] * (base)[0][0] + (base)[0][1] * (base)[1][0], (base)[0][0] * (base)[0][1] + (base)[0][1] * (base)[1][1]],
                    [(base)[1][0] * (base)[0][0] + (base)[1][1] * (base)[1][0], (base)[1][0] * (base)[0][1] + (base)[1][1] * (base)[1][1]]])
            p //= 2
        return result

    if n == 0:
        return 0
    if n == 1:
        return 1

    # Matriz base de Fibonacci
    F = [[1, 1], [1, 0]]
    result = matrix_pow(F, n - 1)
    return result[0][0]


def es_primo_simple(num):
    """Verifica si un número entero es primo usando un método simple."""
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(num)) + 1, 2):
        if num % i == 0:
            return False
    return True


# Precalcular todos los números de Fibonacci hasta 1000 y verificar primalidad
def precalcular_fibonacci_primos(max_n):
    fib_cache = []
    primalidad_cache = []

    for n in range(max_n + 1):
        fib_n = fibonacci(n)
        fib_cache.append(fib_n)
        # Verificamos si el Fibonacci es primo
        if n <= 50:
            primalidad_cache.append("Es primo" if es_primo_simple(fib_n) else "No es primo")
        else:
            primalidad_cache.append("Probablemente sea primo" if es_primo_simple(n) else "No es primo")

    return fib_cache, primalidad_cache


# Función principal
def main():
    fib_cache, primalidad_cache = precalcular_fibonacci_primos(1000)

    try:
        while True:
            n = int(input().strip())
            print(primalidad_cache[n])
    except EOFError:
        pass


if __name__ == "__main__":
    main()

